#include "server/combat/CommandoPolicy.h"
#include "server/combat/RiflemanPolicy.h"
#include "server/scout/GrenadePolicy.h"
#include <nlohmann/json.hpp>
#include <iostream>
#include <cassert>
using Json=nlohmann::json;
using namespace corecu::commando;
int main(int argc,char**){int checks=0;auto check=[&](bool value){++checks;assert(value);};Json out={{"heavy",Json::array()},{"rifle",Json::object()},{"grenade",Json::array()}};
 for(int n=Flame;n<=PistolLauncher;++n){auto f=Family(n);auto s=weapon(f);for(int step=0;step<=18;++step){double train=.1+.05*step;for(int level=0;level<=20;++level){double raw=level/20.,mean=s.qualityLow+(s.qualityHigh-s.qualityLow)*raw,q=quality(f,mean,mean);check(q>=MinimumQuality-1e-9 && q<=1);check(damage(f,q,false,false,train)>0);check(cadence(f,train)>=s.interval);check(action(f,train,true)>=action(f,train));check(referenceCadence(train,q)>=1);check(proficiency(train,q)<=1);if(step>0)check(damage(f,q,false,false,train)+1e-6>=damage(f,q,false,false,train-.05));swgxr::armour::Damage packet(damage(f,q,false,false,train),referenceProfile(f));check(std::abs(packet.total()-DirectRate*s.interval*q*proficiency(train,q)*handling(f))<1e-6);}}
  for(double train:{.1,.55,1.})for(double raw:{0.,.5,1.}){double mean=s.qualityLow+(s.qualityHigh-s.qualityLow)*raw,q=quality(f,mean,mean);Json row={{"family",s.name},{"progression",train},{"source_quality",raw},{"quality_multiplier",q},{"cadence",cadence(f,train)},{"charged",s.charged},{"range",s.range},{"damage",damage(f,q,false,false,train)},{"focused_damage",damage(f,q,true,false,train)},{"action",action(f,train)},{"focused_action",action(f,train,false,true)},{"overdrive_action",action(f,train,true)},{"focused_overdrive_action",action(f,train,true,true)},{"mind",mind(f)},{"focused_mind",mind(f,true)}};
   row["mitigation"]=Json::object();for(auto test:{std::pair<const char*,std::pair<double,double>>{"unarmoured",{0,0}},{"body50",{.5,0}},{"body50_element50",{.5,.5}}}){swgxr::armour::Damage p(1,referenceProfile(f));p.mitigate(test.second.first,test.second.second);row["mitigation"][test.first]=p.total();}out["heavy"].push_back(row);}
 }
 for(int count=0;count<=100;++count){std::vector<double> input(count,.97);auto w=weights(input);check(w.size()<=6);check(std::accumulate(w.begin(),w.end(),0.)<=2.5+1e-9);}
 for(double x=-10;x<=10;x+=.1){auto value=weight({{0,0,0}},{{0,0,1}},{{x,0,5}},12,40,0);check(value>=0 && value<=1);if(std::abs(x)>5*std::tan(20*3.141592653589793/180.))check(value==0);}
 check(weight({{0,0,0}},{{0,0,1}},{{0,0,-1}},12,40,0)==0);check(weight({{0,0,0}},{{0,0,1}},{{0,0,13}},12,40,0)==0);check(weight({{0,0,0}},{{0,0,1}},{{.8,0,12}},24,0,.45,.3)==0);
 check(validImpact({{0,1,0}},{{0,0,1}},{{0,1,30}},48,1,1));check(!validImpact({{0,1,0}},{{0,0,1}},{{5,1,30}},48,1,1));check(!validImpact({{0,1,0}},{{0,0,1}},{{0,1,30}},48,1,.1));check(!validImpact({{0,1,0}},{{0,0,1}},{{0,1,60}},48,2,2));check(classify("object/weapon/ranged/rifle/rifle_lightning.iff")==None);
 for(auto id:{"lethal_shot","piercing_shot","flurry_shot","surprise_shot","sniper_shot","rifleman_focus"}){auto a=corecu::rifleman::ability(id);out["rifle"][id]={{"damage",corecu::rifleman::damage(id,true)},{"action",a.action},{"mind",a.mind},{"cooldown",a.cooldown}};}
 out["rifle_mitigation"]=Json::object();for(auto test:{std::pair<const char*,std::pair<double,double>>{"unarmoured",{0,0}},{"body50",{.5,0}},{"body50_element50",{.5,.5}}}){swgxr::armour::Damage p(1,swgxr::armour::weapon(swgxr::armour::Energy,3));p.mitigate(test.second.first,test.second.second);out["rifle_mitigation"][test.first]=p.total();swgxr::armour::Damage pierce(1,swgxr::armour::weapon(swgxr::armour::Energy,3));pierce.mitigate(test.second.first*.5,test.second.second);out["rifle_mitigation"][std::string(test.first)+"_piercing"]=pierce.total();}
 auto frag=corecu::grenade::spec("object/weapon/ranged/grenade/grenade_fragmentation.iff");for(int speed:{0,20,40})for(double q:{0.,.5,1.}){Json row={{"speed",speed},{"quality",q},{"packet",corecu::grenade::packet(frag,speed,corecu::grenade::quality(frag,200+96*q,400+1050*q))},{"cooldown",corecu::grenade::recovery(speed)}};row["mitigation"]=Json::object();for(auto test:{std::pair<const char*,std::pair<double,double>>{"unarmoured",{0,0}},{"body50",{.5,0}},{"body50_element50",{.5,.5}}}){swgxr::armour::Damage p(1,swgxr::armour::weapon(swgxr::armour::Blast,1));p.mitigate(test.second.first,test.second.second);row["mitigation"][test.first]=p.total();}out["grenade"].push_back(row);}
 out["checks"]=checks;if(argc>1)std::cout<<out.dump();else std::cout<<checks<<" Commando policy geometry, progression, quality, costs, conversion and budget checks passed\n";
}
